package com.revayato.app;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;

/** Native authentication portal: login, registration and password recovery. */
public final class AuthActivity extends Activity{
 final ExecutorService io=Executors.newSingleThreadExecutor();final int BG=0xff050807,CARD=0xff151b18,LIME=0xffd8ff3e;LinearLayout form;ProgressBar busy;TextView error;float zs=1f;
  @Override public void onCreate(Bundle b){super.onCreate(b);zs=Math.max(.95f,Math.min(1.35f,getResources().getConfiguration().fontScale));getWindow().setStatusBarColor(BG);render("login");}
 void render(String mode){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setPadding(dp(22),dp(28),dp(22),dp(30));TextView mark=text("ر",34,BG);mark.setGravity(Gravity.CENTER);mark.setTypeface(null,Typeface.BOLD);GradientDrawable markBg=shape(LIME,30);markBg.setStroke(dp(2),0xffffffff);mark.setBackground(markBg);root.addView(mark,new LinearLayout.LayoutParams(dp(64),dp(64)));TextView brand=text("روایتو",32,Color.WHITE);brand.setGravity(Gravity.CENTER);brand.setTypeface(null,Typeface.BOLD);root.addView(brand);TextView promise=text("تماشای شخصی‌تر، سریع‌تر و همیشه همراه تو",13,0xffaab5ae);promise.setGravity(Gravity.CENTER);root.addView(promise);LinearLayout perks=new LinearLayout(this);perks.setGravity(Gravity.CENTER);for(String p:new String[]{"ادامه تماشا","فهرست شخصی","پیشنهاد هوشمند"}){TextView item=text("✓ "+p,11,0xffd8ff3e);item.setGravity(Gravity.CENTER);GradientDrawable itemBg=shape(0xff111713,14);itemBg.setStroke(dp(1),0xff334139);item.setBackground(itemBg);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,dp(38),1);ip.setMargins(dp(3),dp(10),dp(3),dp(14));perks.addView(item,ip);}root.addView(perks,new LinearLayout.LayoutParams(-1,-2));form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);form.setPadding(dp(20),dp(18),dp(20),dp(20));GradientDrawable cardBg=shape(0xff111713,24);cardBg.setStroke(dp(1),0xff344239);form.setBackground(cardBg);form.setElevation(dp(10));form.addView(text(mode.equals("register")?"حساب تازه بساز":mode.equals("reset")?"بازیابی حساب":"خوش برگشتی",23,Color.WHITE));form.addView(text(mode.equals("login")?"برای ادامه وارد حساب خودت شو":mode.equals("register")?"کمتر از یک دقیقه تا دنیای روایتو":"لینک امن بازیابی برایت ارسال می‌شود",13,0xff98a49d));if(!mode.equals("reset")){LinearLayout tabs=new LinearLayout(this);Button loginTab=miniTab("ورود",mode.equals("login"));loginTab.setOnClickListener(v->render("login"));Button registerTab=miniTab("ثبت‌نام",mode.equals("register"));registerTab.setOnClickListener(v->render("register"));tabs.addView(loginTab,new LinearLayout.LayoutParams(0,dp(46),1));tabs.addView(registerTab,new LinearLayout.LayoutParams(0,dp(46),1));form.addView(tabs);}error=text("",13,0xffff8585);form.addView(error);if(mode.equals("register"))registration();else if(mode.equals("reset"))reset();else login();busy=new ProgressBar(this);busy.setVisibility(View.GONE);form.addView(busy);LinearLayout.LayoutParams cardLp=new LinearLayout.LayoutParams(Math.min(dp(520),getResources().getDisplayMetrics().widthPixels-dp(40)),-2);cardLp.setMargins(0,dp(4),0,dp(20));root.addView(form,cardLp);root.addView(text("با ورود، قوانین استفاده و حریم خصوصی روایتو را می‌پذیرید.",11,0xff748078));scroll.addView(root);setContentView(scroll);}
 void login(){EditText id=field("ایمیل یا نام کاربری",false),pass=field("رمز عبور",true);form.addView(id);form.addView(pass);form.addView(passwordToggle(pass));Button submit=button("ورود به روایتو");submit.setOnClickListener(v->{String identity=id.getText().toString().trim(),password=pass.getText().toString();if(identity.length()<3){show("ایمیل یا نام کاربری را کامل وارد کنید");id.requestFocus();return;}if(password.isEmpty()){show("رمز عبور را وارد کنید");pass.requestFocus();return;}try{send("auth/token/",new JSONObject().put("login",identity).put("password",password),j->{session(j);finish();});}catch(Exception e){show(e.getMessage());}});form.addView(submit);Button forgot=link("رمز عبور را فراموش کرده‌ام؟");forgot.setOnClickListener(v->render("reset"));form.addView(forgot);Button register=outline("ساخت حساب رایگان");register.setOnClickListener(v->render("register"));form.addView(register);}
 void registration(){EditText email=field("ایمیل",false),user=field("نام کاربری",false),pass=field("رمز عبور (حداقل ۸ کاراکتر)",true);form.addView(email);form.addView(user);form.addView(pass);form.addView(passwordToggle(pass));TextView guide=text("برای امنیت بیشتر از حروف و عدد استفاده کنید",12,0xff98a49d);form.addView(guide);Button submit=button("ساخت حساب من");submit.setOnClickListener(v->{String mail=email.getText().toString().trim(),name=user.getText().toString().trim(),password=pass.getText().toString();if(!android.util.Patterns.EMAIL_ADDRESS.matcher(mail).matches()){show("یک ایمیل معتبر وارد کنید");email.requestFocus();return;}if(name.length()<3){show("نام کاربری باید حداقل ۳ کاراکتر باشد");user.requestFocus();return;}if(password.length()<8){show("رمز عبور باید حداقل ۸ کاراکتر باشد");pass.requestFocus();return;}try{send("auth/register/",new JSONObject().put("email",mail).put("username",name).put("password",password),j->{session(j);finish();});}catch(Exception e){show(e.getMessage());}});form.addView(submit);Button back=outline("قبلاً حساب ساخته‌ام · ورود");back.setOnClickListener(v->render("login"));form.addView(back);}
 void reset(){EditText email=field("ایمیل حساب",false);Button submit=button("ارسال لینک بازیابی");submit.setOnClickListener(v->{try{send("auth/password-reset/",new JSONObject().put("email",email.getText().toString().trim()),j->{new AlertDialog.Builder(this).setTitle("ایمیل ارسال شد").setMessage(j.optString("detail","اگر حسابی وجود داشته باشد، لینک بازیابی ارسال می‌شود.")).setPositiveButton("باشه",(d,w)->render("login")).show();});}catch(Exception e){show(e.getMessage());}});form.addView(email);form.addView(submit);Button back=link("بازگشت به ورود");back.setOnClickListener(v->render("login"));form.addView(back);}
 EditText field(String hint,boolean password){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(Color.WHITE);e.setHintTextColor(0xff849087);e.setTextSize(15*zs);e.setSingleLine();e.setPadding(dp(18),0,dp(18),0);GradientDrawable bg=shape(CARD,17);bg.setStroke(dp(2),0xff3c4c42);e.setBackground(bg);if(password)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);e.setLayoutParams(new LinearLayout.LayoutParams(-1,Math.round(dp(60)*zs)){{setMargins(0,dp(7),0,dp(7));}});return e;}CheckBox passwordToggle(EditText pass){CheckBox c=new CheckBox(this);c.setText("نمایش رمز عبور");c.setTextColor(0xffb2bcb6);c.setButtonTintList(android.content.res.ColorStateList.valueOf(LIME));c.setOnCheckedChangeListener((v,checked)->{int p=pass.getSelectionStart();pass.setInputType(InputType.TYPE_CLASS_TEXT|(checked?InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD:InputType.TYPE_TEXT_VARIATION_PASSWORD));pass.setSelection(Math.max(0,p));});return c;}
 Button button(String title){Button b=styled(title,LIME,BG,0xfff1ffb9);b.setElevation(dp(6));return b;}
 Button outline(String title){return styled(title,Color.TRANSPARENT,Color.WHITE,0x8878916f);}
 Button miniTab(String title,boolean active){Button b=styled(title,active?0xcc263229:Color.TRANSPARENT,active?LIME:0xff9ba69f,active?0xff7f9a74:0x5528342c);b.setLayoutParams(null);return b;}
 Button styled(String title,int fill,int color,int border){Button b=AppButtonFactory.create(this,title,fill,color,border,zs);b.setTextSize(15*zs);b.setLayoutParams(new LinearLayout.LayoutParams(-1,Math.round(dp(58)*zs)){{setMargins(0,dp(12),0,dp(6));}});return b;}
 Button link(String title){Button b=styled(title,Color.TRANSPARENT,0xffc9d0cc,0x552e3a33);b.setLayoutParams(new LinearLayout.LayoutParams(-1,Math.round(dp(48)*zs)));return b;}
 void send(String path,JSONObject body,java.util.function.Consumer<JSONObject> ok){busy.setVisibility(View.VISIBLE);error.setText("");io.execute(()->{try{Session.Reply reply=Session.post(this,Session.API+path,body);if(!reply.ok())throw new IOException(reply.message());JSONObject j=new JSONObject(reply.raw.trim().isEmpty()?"{}":reply.raw);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;busy.setVisibility(View.GONE);ok.accept(j);});}catch(Exception e){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;show(e.getMessage());});}});}
 void session(JSONObject j){Session.save(this,j);Toast.makeText(this,"خوش آمدید",Toast.LENGTH_LONG).show();}void show(String s){busy.setVisibility(View.GONE);error.setText("  !  "+(s==null?"درخواست انجام نشد":s));error.setPadding(dp(12),dp(10),dp(12),dp(10));GradientDrawable bg=shape(0xaa351a1e,14);bg.setStroke(dp(1),0x99ff8585);error.setBackground(bg);}
 TextView text(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z*zs);t.setTextColor(c);t.setGravity(Gravity.RIGHT);t.setPadding(0,dp(8),0,dp(8));return t;}GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
}
